Ext.define('bcp.view.RoutingHistoryViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.routinghistory',

    loadHistoryById: function (requestId) {
        var store = Ext.getStore('RoutingHistory');
        store.proxy.url = '/empbc/v1/routes/' + requestId + '/routeHistory';
        store.load();
    },

    onReload: function (tool, e, owner, eOpts) {
        var store = Ext.getStore('RoutingHistory');
        store.reload();
    },

    onViewBeforeShow: function (component, eOpts) {
        var store = Ext.getStore('RoutingHistory'),
            req = this.getViewModel().get('generalInfo'),
            reqId = 0;

        if (req) {
            reqId = req.data.requestId;
        }

        store.proxy.url = '/empbc/v1/routes/' + reqId + '/routeHistory';
        store.load();
    },

    onPanelAdded: function (component, container, pos, eOpts) {
        //need to fire this custom event for the parent container to scroll the requests grid
        //to the selected record because the grid somehow auto scroll to the top when this
        //store is loaded which makes the selected row not visible
        //NOTE: if date is null, it means it's a planned but not executed route and we don't want to display it
        var store = Ext.getStore('RoutingHistory'),
            view = this.lookupReference('routeDataView');
        store.on(
            'load',
            function (operation, records, success) {
                //if we want to show planned routes in the history, we might want to use different icons for planned routes
                //fa-user (means a step not reached yet), fa-user-check (means approved), fa-user-edit (means currently reviewing/current step)
                //for now, we will hide planned routes(date is null) from users
                var tpl = new Ext.XTemplate(
                    '<tpl for=".">',
                    '<tpl for="data">',
                    '<tpl if="date==null">',
                    '    <div />',
                    '<tpl else> ',
                    '<div class="route-item{routeBy:this.cls(values,parent[xindex-2],xindex-1,xcount)}">',
                    '                ',
                    '                <div class="profile-pic-wrap">',
                    '                    <i class="fas fa-user fa-3x" aria-hidden="true"></i>',
                    '                    <div>{date:this.elapsed}</div>',
                    '                </div>',
                    '                <div class="line-wrap">',
                    '                    <div class="contents-wrap">',
                    '                    <tpl if="notes!=null && notes.indexOf(\'routed back the request to a previous stage\')!==-1">',
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:orange;">routed back</span></span> this request to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    '                    <tpl elseif="dynamicType === \'DR\'">',
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:orange;">dynamically rerouted</span></span> this request to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    "                    <tpl elseif=\"dynamicType === 'AA'\">",
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:orange;">approved and dynamically routed</span></span> this request to <span style="font-weight:bold;">{routeToName}</span> for additional approval. </div>',
                    '                    <tpl elseif="dynamicType === \'ITSO\'">',
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:brown;">dynamically rerouted</span></span> this request to the ITSO <span style="font-weight:bold;">{routeToName}</span> for approval. </div>',
                    '                    <tpl elseif="isDynamic === 1">',
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} reviewed</span></span> this request and routed it to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    '                    <tpl elseif="rerouteByName !== \'\'">',
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:purple;">re-assigned</span></span> this request to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    '                    <tpl elseif="isDynamic === 0 && isDynamicReroute === 1">',
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} approved</span></span> this request and routed it to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    "                    <tpl elseif=\"typeName === 'approved' || typeName === 'reviewed'  || typeName === 'sent to FCO'\">",
                    '                        <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:green;">approved</span></span> this request and routed it to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    "                    <tpl elseif=\"typeName === 'sent to DC' || typeName === 'sent to DR'\">",
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:orange;">approved and routed</span></span> this request to <span style="font-weight:bold;">{routeToName}</span> for additional approval (Mission Critical). </div>',
                    "                    <tpl elseif=\"typeName == 'rejected' || typeName == 'returned' \">",
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:red;">{typeName}</span></span> this request and routed it back to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    "                    <tpl elseif=\"typeName == 'submitted' || typeName == 're-submitted'\">",
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} <span style="color:blue;">{typeName}</span></span> this request and routed it to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    "                    <tpl elseif=\"typeName == 'saved' || typeName == 'canceled' || typeName == 'ordered' || typeName == 'delivered' \">",
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} {typeName}</span> this request.</div>',
                    '                    <tpl else>                   ',
                    '                         <div class="shared-by"><span style="font-weight:bold;">{routeByName} {typeName}</span> this request and routed it to <span style="font-weight:bold;">{routeToName}.</span> </div>',
                    '                    </tpl>',
                    '                         <div class="article-comment">{notes}</div>',
                    '                    </div>',
                    '                </div>',
                    '</div>',
                    '</tpl>',
                    '</tpl>',
                    '</tpl>',
                    {
                        cls: function (value, record, previous, index, count) {
                            var cls = '';

                            if (!index) {
                                cls += ' route-item-first';
                            }
                            if (index + 1 === count) {
                                cls += ' route-item-last';
                            }

                            return cls;
                        },
                        elapsed: function (value) {
                            return value.toLocaleDateString();
                        }
                    }
                );
                //sometimes, the view.el.dom is not rendered correctly and has undefined as value
                if (view && view.el) {
                    tpl.overwrite(view.el.dom, records);
                }
                //scrollbar sometimes was not set to correct height so
                //manually set the height to adjust it
                this.view.setHeight(this.view.height + 1);
            },
            this
        );
    }
});
